const form=document.querySelector('#gate-form'),password=document.querySelector('#password'),status=document.querySelector('#status'),submit=document.querySelector('#submit');
document.querySelector('#show-password').onclick=()=>{const hidden=password.type==='password';password.type=hidden?'text':'password';document.querySelector('#show-password').textContent=hidden?'숨김':'표시';};
form.onsubmit=async e=>{e.preventDefault();if(submit.disabled)return;submit.disabled=true;status.textContent='확인 중…';const entered=password.value;password.value='';try{const r=await fetch('/api/auth',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',password:entered})});const d=await r.json();if(!r.ok)throw Error(d.error||'접속에 실패했습니다.');location.replace('/');}catch(e){status.textContent=e.message;password.focus();}finally{submit.disabled=false;}};
(async()=>{try{const r=await fetch('/api/auth',{credentials:'same-origin'});const d=await r.json();if(d.user)location.replace('/');else if(!d.configured)status.textContent='관리자의 서버 설정을 기다리고 있습니다.';}catch{status.textContent='서버 연결을 확인해주세요.';}})();
